def _chunk_text(text: str, target_size: int = 30) -> list[str]:
    """Split text into word-boundary chunks for streaming effect."""
    chunks: list[str] = []
    current = ""
    for word in text.split(" "):
        candidate = current + (" " if current else "") + word
        if len(candidate) >= target_size:
            chunks.append(candidate)
            current = ""
        else:
            current = candidate
    if current:
        chunks.append(current)
    return chunks

