 14→async function streamSSE(
 15→  response: Response,
 16→  callbacks: AgentCallbacks,
 17→  signal?: AbortSignal,
 18→): Promise<void> {
 19→  const reader = response.body?.getReader();
 20→  if (!reader) {
 21→    callbacks.onError('No response stream');
 22→    return;
 23→  }
 24→
 25→  try {
 26→    const decoder = new TextDecoder();
 27→    let buffer = '';
 28→    let eventType = '';
 29→
 30→    while (true) {
 31→      const { done, value } = await reader.read();
 32→      if (done) break;
 33→
 34→      buffer += decoder.decode(value, { stream: true });
 35→      const lines = buffer.split('\n');
 36→      buffer = lines.pop() ?? '';
 37→      for (const line of lines) {
 38→        if (line.startsWith('event: ')) {
 39→          eventType = line.slice(7).trim();
 40→        } else if (line.startsWith('data: ')) {
 41→          const data = line.slice(6);
 42→          try {
 43→            const parsed = JSON.parse(data);
 44→            handleSSEEvent(eventType, parsed, callbacks);
 45→          } catch {
 46→            // Skip malformed JSON
 47→          }
 48→          eventType = '';
 49→        }
 50→      }
 51→    }
 52→  } catch (e: unknown) {
 53→    if (signal?.aborted) return;
 54→    const msg = e instanceof Error ? e.message : 'Connection failed';
 55→    callbacks.onError(msg);
 56→  }
 57→}
