```python
import asyncio
from datetime import datetime, timedelta, timezone
from unittest.mock import AsyncMock, MagicMock, patch, PropertyMock

import pytest

from app.container_manager import ContainerManager, ContainerInfo, ContainerConfig


@pytest.fixture
def config():
