102→  callbacks: AgentCallbacks,
103→  signal?: AbortSignal,
104→  userSessionId?: string,
105→): Promise<void> {
106→  try {
107→    const response = await fetch('/api/chat/edit', {
108→      method: 'POST',
109→      headers: {
110→        'Content-Type': 'application/json',
111→        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
112→      },
113→      body: JSON.stringify({
114→        new_message: newMessage,
115→        conversation_history: conversationHistory,
116→        langfuse_session_id: langfuseSessionId,
117→      }),
118→      signal,
119→    });
120→
121→    if (!response.ok) {
122→      const errorText = await response.text();
123→      callbacks.onError(`Server error: ${errorText}`);
124→      return;
125→    }
126→
127→    await streamSSE(response, callbacks, signal);
128→  } catch (e: unknown) {
129→    if (signal?.aborted) return;
130→    const msg = e instanceof Error ? e.message : 'Connection failed';
131→    callbacks.onError(msg);
132→  }
133→}
134→
135→function handleSSEEvent(
136→  eventType: string,
137→  data: Record<string, unknown>,
138→  callbacks: AgentCallbacks,
139→) {
140→  switch (eventType) {
141→    case 'thinking':
142→    case 'answer':
143→      callbacks.onTextChunk(data.text as string);
144→      break;
145→    case 'thinking_done':
146→      callbacks.onThinkingDone();
147→      break;
148→    case 'tool_call':
149→      callbacks.onToolCall({
150→        toolCallId: (data.id as string) ?? '',
151→        toolName: (data.name as string) ?? undefined,
152→        sql: (data.sql as string) ?? '',
153→        command: (data.command as string) ?? undefined,
154→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
155→        columns: [],
156→        rows: [],
157→        rowCount: 0,
158→      });
159→      break;
160→    case 'tool_result': {
161→      const result: ToolCallResult = {
162→        toolCallId: (data.id as string) ?? '',
163→        toolName: (data.name as string) ?? undefined,
164→        sql: (data.sql as string) ?? '',
165→        columns: (data.columns as string[]) ?? [],
166→        rows: (data.rows as Record<string, unknown>[]) ?? [],
167→        rowCount: (data.rowCount as number) ?? 0,
168→        error: (data.error as string) ?? undefined,
169→        output: (data.output as string) ?? undefined,
170→        rawContent: (data.content as string) ?? undefined,
171→      };
172→      callbacks.onToolResult(result);
173→      break;
174→    }
175→    case 'done':
176→      callbacks.onDone((data.session_id as string) ?? null);
177→      break;
178→    case 'error':
179→      callbacks.onError((data.message as string) ?? 'Unknown error');
180→      break;
181→  }
182→}
